import { db } from 'sdk';
import { eq, desc } from 'sdk/db';
import { notes } from '../schema.js';

export default async function (_input, ctx) {
  return await db.select({ id: notes.id, body: notes.body })
    .from(notes)
    .where(eq(notes.ownerId, ctx.initData.user.id))
    .orderBy(desc(notes.id))
    .all();
}

